 215: /** Prices every run at its own agent's rate, so one card may mix agents without losing either. */
 216: function groupCost(group: ConversationGroup, rates: Map<string, ProviderRate>): GroupCost {
 217:     const agentIdentities = new Set<string>();
 218:     const pricedAgents = new Set<string>();
 219:     const unpricedByReason = new Map<string, number>();
 220:     let value = 0;
 221:     for (const { agent, totalTokens } of group.conversations) {
 222:         agentIdentities.add(agent ?? UNKNOWN_AGENT_LABEL);
 223:         const rate = agent === null ? undefined : rates.get(agent);
 224:         if (rate?.available) {
 225:             value += totalTokens / rate.tokensPerDollar;
 226:             pricedAgents.add(agent!);
 227:             continue;
 228:         }
 229:         const reason = rate?.reason ?? NO_ACCOUNT_SERIES_REASON;
 230:         unpricedByReason.set(reason, (unpricedByReason.get(reason) ?? 0) + 1);
 231:     }
 232:     // An all-unpriced bar still names its agent when there is only one; only real mixing reads as Mixed.
 233:     const namedAgents = pricedAgents.size > 0 ? pricedAgents : agentIdentities;
 234:     const singleAgent = namedAgents.size === 1 ? [...namedAgents][0] : null;
 235: 
 236:     return {
 237:         priced: pricedAgents.size > 0,
 238:         rate: singleAgent ? rates.get(singleAgent) ?? null : null,
 239:         singleAgent,
 240:         unpricedByReason,
 241:         value,
 242:     };
 243: }
