 245: function costRow(
 246:     controls: StatsControls,
 247:     groupIdentity: string,
 248:     group: ConversationGroup,
 249:     rates: Map<string, ProviderRate>,
 250: ): StatsChartRow {
 251:     const { priced, rate, singleAgent, unpricedByReason, value } = groupCost(group, rates);
 252:     const extraLines: StatsTooltipLine[] = [{
 253:         label: 'Priced with',
 254:         value: singleAgent ? `${singleAgent} subscription rate` : 'Mixed agents',
 255:     }];
 256:     for (const [reason, count] of unpricedByReason) {
 257:         extraLines.push({ label: null, value: `Not priced: ${count} run${count === 1 ? '' : 's'} (${reason})` });
 258:     }
 259:     const row = totalRow(controls, groupIdentity, { label: group.label, title: group.title, value }, 'dollars', extraLines);
 260: 
 261:     return {
 262:         ...row,
 263:         agent: singleAgent,
 264:         available: priced,
 265:         denominator: rate?.denominator ?? null,
 266:         limitId: rate?.limitId ?? null,
 267:         numerator: rate?.numerator ?? null,
 268:         provider: singleAgent,
 269:         sampleCount: group.conversations.length,
 270:         seriesIdentity: singleAgent ?? MIXED_AGENT_IDENTITY,
 271:         seriesLabel: singleAgent ?? 'Mixed',
 272:         windowId: rate?.windowId ?? null,
 273:     };
 274: }
